{"function": "() => {
    const article = document.querySelector('article');
    const fullText = article ? article.innerText : document.body.innerText;
    // Find start index for "Version 0.19\n\nAugust 12, 2017"
    const startMarker = 'Version 0.19\n\nAugust 12, 2017';
    let startIdx = fullText.indexOf(startMarker);
    if (startIdx === -1) {
        // fallback
        startIdx = fullText.indexOf('Version 0.19');
    }
    if (startIdx === -1) return fullText;
    // Find next version heading after this one
    const nextVersion = fullText.indexOf('Version 0.19.1', startIdx);
    if (nextVersion === -1) {
        // maybe there is "Version 0.19.2" earlier? Actually 0.19.2 appears before 0.19.1? In text we have 0.19.2 first, then 0.19.1, then 0.19.
        // Let's find next occurrence of "Version 0.19." after startIdx
        const versionRegex = /Version 0\.19\.\d+/g;
        let match;
        let nextIdx = -1;
        versionRegex.lastIndex = startIdx;
        while ((match = versionRegex.exec(fullText)) !== null) {
            if (match.index > startIdx) {
                nextIdx = match.index;
                break;
            }
        }
        if (nextIdx === -1) {
            // no next version, take rest
            return fullText.substring(startIdx);
        }
        return fullText.substring(startIdx, nextIdx);
    }
    return fullText.substring(startIdx, nextVersion);
}"}

